package com.baeldung.conditionalflow.step;

import com.baeldung.conditionalflow.model.NumberInfo;
import org.springframework.batch.item.ItemReader;

public class NumberInfoGenerator implements ItemReader<NumberInfo> {
    private int[] values;
    private int counter;

    public NumberInfoGenerator(int[] values) {
        this.values = values;
        counter = 0;
    }

    @Override
    public NumberInfo read() {
        if (counter == values.length) {
            return null;
        } else {
            return new NumberInfo(values[counter++]);
        }
    }
}

