@JmixEntity
@Table(name = "USER_EXPENSE", indexes = {
        @Index(name = "IDX_USER_EXPENSE_USER", columnList = "USER_ID"),
        @Index(name = "IDX_USER_EXPENSE_EXPENSE", columnList = "EXPENSE_ID")
